#!/usr/bin/env bash
set -euo pipefail

branch=bot/prune-oxlint-suppressions
asset=oxlint-suppressions.json
pr=$(gh pr list --repo "$GITHUB_REPOSITORY" --base master --head "$branch" --state open --json number --jq '.[0].number // empty')

if git diff --quiet HEAD -- "$asset"; then
  if [[ -n "$pr" ]]; then
    gh pr close "$pr" --repo "$GITHUB_REPOSITORY" --comment 'Master no longer needs suppression pruning.'
  fi
  exit 0
fi

observed=$(git ls-remote --heads origin "refs/heads/$branch")
observed=${observed%%$'\t'*}
if [[ -n "$observed" ]]; then
  git fetch --no-tags origin "$observed"
  if [[ -n "$pr" ]] &&
    [[ $(git diff --name-only "HEAD...$observed") == "$asset" ]] &&
    git diff --quiet "$observed" -- "$asset"; then
    exit 0
  fi
fi

git switch -C "$branch"
git add "$asset"
git -c user.name=getsentry-bot \
  -c user.email='10587625+getsentry-bot@users.noreply.github.com' \
  commit --only -m 'chore(lint): prune oxlint suppressions' -- "$asset"
git push --force-with-lease="refs/heads/$branch:$observed" origin "HEAD:refs/heads/$branch"

if [[ -z "$pr" ]]; then
  gh pr create --repo "$GITHUB_REPOSITORY" --base master --head "$branch" \
    --title 'chore(lint): prune oxlint suppressions' \
    --body 'Reduce stale oxlint suppression budgets using a full type-aware scan of master. Generated by `pnpm run lint:js --prune`; existing budgets cannot increase.'
fi
